'use strict';
(() => {
  const $=id=>document.getElementById(id),R=GeoRadarRepresentatives,codes=R.codes,personnel=Object.fromEntries(R.definitions.map(d=>[d.code,d.personnelNumber]));let map,officeMarker,areas={type:'FeatureCollection',features:[]};
  let configuration=codes.map(code=>({code,personnelNumber:personnel[code],rules:[]}));
  const block=document.createElement('section');block.className='territory-controls';
  block.innerHTML='<div class="divider"></div><h3>PLZ & Außendienst</h3><label class="field-label" for="postal-prefix">PLZ oder Präfixe (DE/AT)</label><input id="postal-prefix" type="search" placeholder="88, 89, 78, 88046, 6850" maxlength="1500"><p class="micro">Filtert Standorte und grobe PLZ-Präfixpunkte. Flächen nur mit importierten PLZ-Polygonen.</p><label class="field-label" for="territory-filter">Vertreter (Mehrfachauswahl)</label><select id="territory-filter" multiple size="7"><option value="all" selected>Alle Vertreter</option></select><p class="micro">Mehrere Vertreter mit Strg/Cmd auswählen. Ein Vertreterfilter verändert keine Zuordnung.</p><div id="representative-legend" class="representative-legend" aria-label="Vertreterlegende"></div><p class="micro">GK 10 · alle PLZ-Gebiete · Pumpen, Rührwerke, Kläranlagen, Kommunen, Bäderbetriebe. Fachliche Vorschläge ändern keine Kundenzuordnung.</p><div id="territory-rows"></div><button id="territory-save" class="outline">Gebietszuordnung übernehmen</button><p id="territory-feedback" class="micro" role="status">Personalnummern und PLZ-Gebiete sind noch nicht zugeordnet.</p><details><summary>Echte PLZ-Flächen importieren</summary><label class="field-label" for="postal-source">Quelle / Lizenz des Datensatzes</label><input id="postal-source" type="text" maxlength="1000" placeholder="Quelle und Nutzungsrecht"><label class="field-label" for="postal-file">GeoJSON mit postalCode und country</label><input id="postal-file" type="file" accept=".json,.geojson,application/geo+json,application/json"><p class="micro">Polygon oder MultiPolygon, WGS 84; country DE/AT, postalCode als vollständiger PLZ-Text. Maximal 20 MB. Nur Daten mit geeignetem Nutzungsrecht verwenden.</p></details><p id="postal-feedback" class="micro" role="status">Keine PLZ-Polygonflächen geladen. Die Karte zeigt keine künstlichen Gebietsflächen.</p><button id="office-focus" class="outline">⌂ Mangold-Standort anzeigen</button>';
  $('bridge-state').after(block);
  $('territory-feedback').textContent='Personalnummern: CO 93 · SR 42 · SH 11 · GD 2 · GK 10. GK fachlich für alle PLZ verfügbar; keine automatische Gebietszuordnung.';
  for(const code of codes){const row=document.createElement('details');row.className='territory-row';row.innerHTML='<summary>'+code+' · Personalnummer & PLZ</summary><label class="field-label" for="person-'+code+'">Personalnummer '+code+'</label><input id="person-'+code+'" type="text" maxlength="100"><label class="field-label" for="de-'+code+'">Deutschland · PLZ/Präfixe</label><input id="de-'+code+'" type="text" placeholder="z. B. 88, 89"><label class="field-label" for="at-'+code+'">Österreich · PLZ/Präfixe</label><input id="at-'+code+'" type="text" placeholder="z. B. 68, 69">';$('territory-rows').append(row);}
  for(const code of codes)$('person-'+code).value=personnel[code];
  for(const d of R.definitions){const option=document.createElement('option');option.value=d.code;option.textContent=d.code+' '+d.personnelNumber;$('territory-filter').append(option);const item=document.createElement('span'),dot=document.createElement('i');dot.className='representative-ring';dot.style.borderColor=d.color;item.append(dot,document.createTextNode(d.code+' '+d.personnelNumber));$('representative-legend').append(item);}const unassigned=document.createElement('option');unassigned.value='unassigned';unassigned.textContent='Nicht zugeordnet';$('territory-filter').append(unassigned);
  const layers=[['office-layer','Mangold-Standort','Eigener Standort · separate Markierung'],['postal-labels','PLZ-Beschriftungen','Standorte und grobe Präfixpunkte'],['postal-polygons','PLZ-Flächen','Nur aus echten importierten Polygonen'],...codes.map(code=>['territory-'+code,'Gebiet '+code,'Zuordnung über Personalnummer / PLZ'])];
  for(const [id,title,note]of layers){const label=document.createElement('label');const span=document.createElement('span'),small=document.createElement('small'),check=document.createElement('input');span.textContent=title;small.textContent=note;span.append(small);check.type='checkbox';check.id=id;check.checked=id!=='postal-labels';label.append(span,check);$('layer-controls').append(label);check.onchange=notify;}
  function parse(value){const parts=value.split(/[,;\s]+/).map(x=>x.trim()).filter(Boolean);if(parts.some(p=>!/^\d{1,5}$/.test(p)))throw Error('PLZ-Präfixe dürfen nur aus 1–5 Ziffern bestehen.');return [...new Set(parts)];}
  function belongs(r,t){return R.assignment(r,configuration).includes(t.code);}
  function prefixMatches(r){let prefixes;try{prefixes=parse($('postal-prefix').value);}catch{return false;}return !prefixes.length||prefixes.some(p=>String(r.postalCode||r.postalPrefix||'').startsWith(p));}
  function matches(r){const selection=Array.from($('territory-filter').selectedOptions,o=>o.value),assigned=R.assignment(r,configuration);return prefixMatches(r)&&(!selection.length||selection.includes('all')||selection.some(code=>code==='unassigned'?!assigned.length:assigned.includes(code)));}
  function notify(){document.dispatchEvent(new CustomEvent('georadar:territories-changed'));refresh();}
  $('postal-prefix').oninput=()=>{try{parse($('postal-prefix').value);$('postal-prefix').setCustomValidity('');}catch(e){$('postal-prefix').setCustomValidity(e.message);$('territory-feedback').textContent=e.message;}notify();};
  let previousSelection=['all'];$('territory-filter').onchange=()=>{const options=Array.from($('territory-filter').selectedOptions,o=>o.value);if(options.includes('all')&&options.length>1){if(previousSelection.includes('all'))$('territory-filter').options[0].selected=false;else for(const o of $('territory-filter').options)o.selected=o.value==='all';}if(!$('territory-filter').selectedOptions.length)$('territory-filter').options[0].selected=true;previousSelection=Array.from($('territory-filter').selectedOptions,o=>o.value);notify();};
  function setConfiguration(value){const next=GeoRadarData.validateTerritories(value);if(!next.some(t=>t.code==='GK'))next.push(configuration.find(t=>t.code==='GK')||{code:'GK',personnelNumber:'10',rules:[]});configuration=next;for(const code of codes){const t=configuration.find(t=>t.code===code);$('person-'+code).value=t?.personnelNumber||'';for(const country of ['DE','AT'])$(country.toLowerCase()+'-'+code).value=t?.rules.find(r=>r.country===country)?.prefixes.join(', ')||'';}$('territory-feedback').textContent='Zuordnung übernommen. Überlappende PLZ oder Personalnummern können mehrere Gebiete ergeben.';notify();}
  $('territory-save').onclick=()=>{try{setConfiguration(codes.map(code=>({code,personnelNumber:$('person-'+code).value,rules:['DE','AT'].map(country=>({country,prefixes:parse($(country.toLowerCase()+'-'+code).value)}))})));}catch(e){$('territory-feedback').textContent='Nicht übernommen: '+e.message;}};
  function validateAreas(data){
    if(!data||data.type!=='FeatureCollection'||!Array.isArray(data.features)||data.features.length>30000)throw Error('GeoJSON FeatureCollection mit höchstens 30.000 Flächen erforderlich.');
    let points=0;return {type:'FeatureCollection',features:data.features.map((f,index)=>{
      const p=f.properties||{},country=p.country==='DE'?'Deutschland':p.country==='AT'?'Österreich':undefined;if(!country||typeof p.postalCode!=='string'||!(p.country==='DE'?/^\d{5}$/:/^\d{4}$/).test(p.postalCode))throw Error('Fläche '+(index+1)+': country DE/AT und vollständige postalCode als Text erforderlich.');
      if(!['Polygon','MultiPolygon'].includes(f.geometry?.type))throw Error('Nur Polygon und MultiPolygon werden unterstützt.');
      const polygons=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;if(!Array.isArray(polygons)||!polygons.length)throw Error('Leere Geometrie.');
      for(const polygon of polygons){if(!Array.isArray(polygon)||!polygon.length)throw Error('Polygon ohne Ring.');for(const ring of polygon){if(!Array.isArray(ring)||ring.length<4)throw Error('Ungültiger Polygonring.');for(const point of ring){points++;if(points>500000)throw Error('Maximal 500.000 Koordinaten je Import.');if(!Array.isArray(point)||point.length<2||!Number.isFinite(point[0])||!Number.isFinite(point[1])||point[0]<5||point[0]>18||point[1]<46||point[1]>56)throw Error('Geometrie muss im DE/AT-Kartenausschnitt und WGS 84 liegen.');}if(ring[0][0]!==ring.at(-1)[0]||ring[0][1]!==ring.at(-1)[1])throw Error('Polygonring muss geschlossen sein.');}}
      return {type:'Feature',properties:{postalCode:p.postalCode,country},geometry:f.geometry};
    })};
  }
  $('postal-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('Maximal 20 MB.');if(!$('postal-source').value.trim())throw Error('Bitte Quelle und Nutzungsrecht angeben.');const next=validateAreas(JSON.parse(await f.text()));areas=next;$('postal-feedback').textContent=areas.features.length+' importierte PLZ-Flächen · Quelle: '+$('postal-source').value+' · Vollständigkeit/Genauigkeit nicht amtlich geprüft.';refresh();}catch(error){$('postal-feedback').textContent='Flächen nicht übernommen: '+error.message;}};
  function refresh(){
    if(!map)return;
    if(officeMarker)officeMarker.getElement().hidden=!$('office-layer').checked;
    const snapshot=window.GeoRadarCompanies.getSnapshot(),active=configuration.filter(t=>$('territory-'+t.code).checked),countryFilter=$('country').value;
    const rows=window.GeoRadarCompanies.getFilteredRecords();
    const features=rows.map(r=>{const p=GeoRadarData.position(r);return p?{type:'Feature',geometry:{type:'Point',coordinates:p.coordinates},properties:{postalCode:r.postalCode||r.postalPrefix||'',postalLabel:GeoRadarData.postalLabel(r)+(p.isPrefix?' · Gebietspunkt':' · Standort'),codes:active.filter(t=>belongs(r,t)).map(t=>t.code).join(' / ')}}:null;}).filter(Boolean);
    map.getSource('postal-sites')?.setData({type:'FeatureCollection',features});
    const areaFeatures=areas.features.filter(f=>prefixMatches(f.properties)&&(countryFilter==='both'||f.properties.country===(countryFilter==='de'?'Deutschland':'Österreich'))).map(f=>{const all=configuration.filter(t=>belongs(f.properties,t));const visible=all.filter(t=>active.some(v=>v.code===t.code));if(all.length&&!visible.length)return null;return {...f,properties:{...f.properties,codes:visible.map(t=>t.code).join(' / ')}};}).filter(Boolean);
    map.getSource('postal-areas')?.setData({type:'FeatureCollection',features:areaFeatures});
    for(const id of ['postal-area-fill','postal-area-line','postal-area-label'])if(map.getLayer(id))map.setLayoutProperty(id,'visibility',$('postal-polygons').checked?'visible':'none');
    if(map.getLayer('postal-site-label'))map.setLayoutProperty('postal-site-label','visibility',$('postal-labels').checked?'visible':'none');
  }
  $('country').addEventListener('change',refresh);document.querySelectorAll('[data-area]').forEach(b=>b.addEventListener('click',refresh));$('reset').addEventListener('click',refresh);
  document.addEventListener('georadar:companies-updated',refresh);
  document.addEventListener('georadar:map-ready',event=>{
    map=event.detail;
    const pin=document.createElement('button');pin.className='office-pin';pin.textContent='M';pin.title='Mangold GmbH · eigener Standort';pin.setAttribute('aria-label','Mangold GmbH – eigener Standort, Lindauer Straße 116, 88046 Friedrichshafen');
    const info=document.createElement('div');info.innerHTML='<h3>Mangold GmbH · Unser Standort</h3><p>Lindauer Straße 116<br>88046 Friedrichshafen</p><p>Position nach Kartenreferenz der Unternehmenswebsite; ungefähr, kein Vermessungsnachweis.</p><a href="https://www.mangoldgmbh.com/kontakt" target="_blank" rel="noreferrer">Standortquelle</a>';
    officeMarker=new maplibregl.Marker({element:pin}).setLngLat([9.508511741063957,47.64373714669217]).setPopup(new maplibregl.Popup({maxWidth:'300px'}).setDOMContent(info)).addTo(map);
    map.addSource('postal-sites',{type:'geojson',data:{type:'FeatureCollection',features:[]}});
    map.addLayer({id:'territory-site-ring',type:'circle',source:'companies',filter:['all',['!',['has','point_count']],['!=',['get','repCode'],'']],paint:{'circle-radius':13,'circle-color':'#ffffff','circle-opacity':0,'circle-stroke-width':3,'circle-stroke-color':['match',['get','repCode'],...R.definitions.flatMap(d=>[d.code,d.color]),'#173a55']}});
    map.addLayer({id:'territory-site-label',type:'symbol',source:'postal-sites',filter:['!=',['get','codes'],''],layout:{'text-field':['get','codes'],'text-font':['Noto Sans Bold'],'text-size':11,'text-offset':[0,-1.7]},paint:{'text-color':'#153c59','text-halo-color':'#ffffff','text-halo-width':1.5}});
    map.addLayer({id:'postal-site-label',type:'symbol',source:'postal-sites',layout:{visibility:'none','text-field':['get','postalLabel'],'text-font':['Noto Sans Regular'],'text-size':10,'text-offset':[0,1.8]},paint:{'text-color':'#173a55','text-halo-color':'#ffffff','text-halo-width':1.3}});
    map.addControl({onAdd(){const el=document.createElement('div');el.className='maplibregl-ctrl maplibregl-ctrl-attrib';const a=document.createElement('a');a.href='https://www.geonames.org/';a.target='_blank';a.rel='noreferrer';a.textContent='PLZ-Präfixpunkte: GeoNames (CC BY 4.0)';el.append(a);return this.el=el;},onRemove(){this.el?.remove();}},'bottom-right');
    map.addSource('postal-areas',{type:'geojson',data:areas});
    map.addLayer({id:'postal-area-fill',type:'fill',source:'postal-areas',paint:{'fill-color':'#376e98','fill-opacity':.16}},'company-clusters');
    map.addLayer({id:'postal-area-line',type:'line',source:'postal-areas',paint:{'line-color':'#214d71','line-width':1.5}},'company-clusters');
    map.addLayer({id:'postal-area-label',type:'symbol',source:'postal-areas',layout:{'text-field':['concat',['get','codes'],' ',['get','postalCode']],'text-font':['Noto Sans Bold'],'text-size':11},paint:{'text-color':'#153c59','text-halo-color':'#ffffff','text-halo-width':1.2}});
    $('office-focus').onclick=()=>{ $('office-layer').checked=true;refresh();map.flyTo({center:[9.508511741063957,47.64373714669217],zoom:15,duration:700});officeMarker.togglePopup();};refresh();
  });
  window.GeoRadarTerritories={matches,setConfiguration,representativeFor:r=>R.assignment(r,configuration).find(code=>$('territory-'+code)?.checked)||'',getConfiguration:()=>JSON.parse(JSON.stringify(configuration))};
})();
